import React from "react";

const cityDestinations = {
  Varanasi: [
    {
      name: "Dashashwamedh Ghat",
      description: "Experience the world-famous Ganga Aarti and the vibrant evening atmosphere.",
      bestTime: "Evening (6 PM - 8 PM)",
      safety: "Safe but crowded",
    },
    {
      name: "Kashi Vishwanath Temple",
      description: "A sacred temple dedicated to Lord Shiva, central to the spiritual soul of India.",
      bestTime: "Morning (5 AM - 9 AM)",
      safety: "Safe",
    },
    {
      name: "Sarnath",
      description: "Important Buddhist site with stupas and museums.",
      bestTime: "Morning",
      safety: "Safe",
    },
  ],
  Jaipur: [
    { name: "Hawa Mahal", description: "Iconic pink sandstone palace.", bestTime: "Morning", safety: "Safe" },
    { name: "Amber Fort", description: "Historic fort with elephant rides.", bestTime: "Afternoon", safety: "Safe" },
    { name: "City Palace", description: "Royal palace complex.", bestTime: "Anytime", safety: "Safe" },
  ],
  Delhi: [
    { name: "India Gate", description: "War memorial and gardens.", bestTime: "Evening", safety: "Safe" },
    { name: "Red Fort", description: "Mughal-era fortress.", bestTime: "Morning", safety: "Safe" },
    { name: "Qutub Minar", description: "Historic minaret.", bestTime: "Morning", safety: "Safe" },
  ],
};

export default function RoutePlanner({ tourist, onProceed }) {
  const keyCapitalized = tourist?.city ? tourist.city : "";
  const places = cityDestinations[keyCapitalized] || [];

  return (
    <div style={rootStyle}>
      <div style={containerStyle}>
        <h1 style={{ color: "#A0522D", marginBottom: "10px" }}>🌍 My Journey</h1>
        <p style={{ fontSize: "1.05rem", color: "#333", marginBottom: "20px" }}>
          Welcome, <strong>{tourist?.name}</strong>! Here are some recommended places for <strong>{tourist?.city || "your city"}</strong>.
        </p>

        <div style={{ maxHeight: 360, overflowY: "auto", textAlign: "left", paddingRight: 10 }}>
          {places.length > 0 ? (
            places.map((dest, idx) => (
              <div key={idx} style={placeCard}>
                <h3 style={{ color: "#D2691E", marginBottom: 6 }}>📍 {dest.name}</h3>
                <p style={{ marginBottom: 6 }}>{dest.description}</p>
                <p style={{ margin: 0, fontSize: 13 }}>
                  <strong>🕐 Best Time:</strong> {dest.bestTime} &nbsp; <strong>🔒 Safety:</strong> {dest.safety}
                </p>
              </div>
            ))
          ) : (
            <p style={{ color: "#555" }}>No curated places for this city yet. You can still proceed to plan your journey.</p>
          )}
        </div>

        <button onClick={onProceed} style={proceedButton}>
          🚶‍♂️ Start My Journey
        </button>
      </div>
    </div>
  );
}

const rootStyle = {
  background: "linear-gradient(135deg, #FFB75E, #ED8F03)",
  minHeight: "100vh",
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
  padding: "40px",
};

const containerStyle = {
  backgroundColor: "rgba(255, 255, 255, 0.95)",
  borderRadius: 20,
  padding: 30,
  boxShadow: "0 8px 20px rgba(0,0,0,0.2)",
  width: "90%",
  maxWidth: 700,
  textAlign: "center",
};

const placeCard = {
  backgroundColor: "rgba(255,255,255,0.96)",
  borderRadius: 12,
  padding: 14,
  marginBottom: 12,
  boxShadow: "0 4px 10px rgba(0,0,0,0.08)",
};

const proceedButton = {
  marginTop: 18,
  backgroundColor: "#FF7A00",
  border: "none",
  color: "white",
  padding: "12px 20px",
  borderRadius: 10,
  fontSize: "1rem",
  cursor: "pointer",
};
